private void xrLabel27_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
  e.Result = totalimetvsh - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE"));
            likujdimi = totalimetvsh - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) - Convert.ToDouble(GetCurrentColumnValue("VleraMbetur"));
            e.Handled = true;
}

private void xrLabel27_SummaryReset(object sender, System.EventArgs e) {
 totalimetvsh = 0;
}

private void xrLabel27_SummaryRowChanged(object sender, System.EventArgs e) {
 totalimetvsh += Convert.ToDouble(GetCurrentColumnValue("VLEFTAMETVSH"));
}

